    x, y = agent_pos

    resources = observation.get('resources', [])
    prey_positions = observation.get('prey_positions', [])
    predator_positions = observation.get('predator_positions', [])
    territory_map = observation.get('territory_map', [])
    my_territory = None
    if territory_map:
        if 0 <= y < len(territory_map) and 0 <= x < len(territory_map[0]):
            my_territory = territory_map[y][x]

    def neighbors(pos):
        nx, ny = pos
        return [(nx + dx, ny + dy) for dx in [-1,0,1] for dy in [-1,0,1] if (dx != 0 or dy != 0)]

    moves = [(-1,0), (1,0), (0,-1), (0,1)]
    move_candidates = []

    def direction_towards(src, target):
        dx = target[0] - src[0]
        dy = target[1] - src[1]
        step_x = 0
        step_y = 0
        if dx != 0:
            step_x = dx // abs(dx)
        if dy != 0:
            step_y = dy // abs(dy)
        return (step_x, step_y)

    # 1. Move towards closest resource
    if resources:
        closest_res = min(resources, key=lambda r: abs(r[0] - x) + abs(r[1] - y))
        dx, dy = direction_towards(agent_pos, closest_res)
        if (dx, dy) in moves:
            return [dx, dy]
        else:
            move_candidates.extend(moves)

    # 2. Chase prey if nearby
    if prey_positions:
        prey = min(prey_positions, key=lambda p: abs(p[0] - x) + abs(p[1] - y))
        dx, dy = direction_towards(agent_pos, prey)
        if (dx, dy) in moves:
            return [dx, dy]
        else:
            move_candidates.extend(moves)

    # 3. Move towards own territory if known
    if my_territory is not None:
        for nx, ny in neighbors(agent_pos):
            if 0 <= ny < len(territory_map) and 0 <= nx < len(territory_map[0]):
                if territory_map[ny][nx] == my_territory:
                    dx = nx - x
                    dy = ny - y
                    if (dx, dy) in moves:
                        return [dx, dy]
        # fallback: stay put
        return [0, 0]

    # 4. Default to random move from candidates
    for dx, dy in move_candidates:
        if (dx, dy) in moves:
            return [dx, dy]
    return [0, 0]

